#!/usr/bin/env bash # shims.sh - Cross-platform command shims # Source this file to get platform-independent commands
# =========================================================================== # Platform Detection (cached for performance) # ===========================================================================
__detect_os() { case "$(uname -s)" in Linux*) echo "linux" ;; Darwin*) echo "macos" ;; MINGW*|MSYS*|CYGWIN*) echo "windows" ;; *) echo "unknown" ;; esac }
__detect_wsl() { [[ -f /proc/version ]] && grep -qi microsoft /proc/version 2>/dev/null }
# Cache platform detection readonly __SHIM_OS="$(__detect_os)" readonly __SHIM_WSL="$(__detect_wsl && echo "true" || echo "false")"
# =========================================================================== # Clipboard Shims # ===========================================================================
# Copy stdin to clipboard clip() { case "$__SHIM_OS" in macos) pbcopy ;; linux) if [[ "$__SHIM_WSL" == "true" ]]; then clip.exe elif [[ -n "${WAYLAND_DISPLAY:-}" ]] && command -v wl-copy &>/dev/null; then wl-copy elif command -v xclip &>/dev/null; then xclip -selection clipboard elif command -v xsel &>/dev/null; then xsel --clipboard --input else echo "No clipboard tool available" >&2 return 1 fi ;; windows) clip ;; esac }
# Paste from clipboard paste() { case "$__SHIM_OS" in macos) pbpaste ;; linux) if [[ "$__SHIM_WSL" == "true" ]]; then powershell.exe -command "Get-Clipboard" | tr -d '\r' elif [[ -n "${WAYLAND_DISPLAY:-}" ]] && command -v wl-paste &>/dev/null; then wl-paste elif command -v xclip &>/dev/null; then xclip -selection clipboard -o elif command -v xsel &>/dev/null; then xsel --clipboard --output else echo "No clipboard tool available" >&2 return 1 fi ;; windows) powershell.exe -command "Get-Clipboard" | tr -d '\r' ;; esac }
# =========================================================================== # File/URL Opening Shims # ===========================================================================
# Open file or URL with default application o() { local target="${1:-.}"
case "$__SHIM_OS" in macos) open "$target" ;; linux) if [[ "$__SHIM_WSL" == "true" ]]; then # WSL: Use Windows explorer for files, browser for URLs if [[ "$target" =~ ^https?:// ]]; then cmd.exe /c start "$target" 2>/dev/null else explorer.exe "$(wslpath -w "$target")" 2>/dev/null fi else xdg-open "$target" &>/dev/null & fi ;; windows) start "$target" ;; esac }
# =========================================================================== # Editor Shims # ===========================================================================
# Smart editor selection e() { local file="${1:-}" local editors=("${EDITOR:-}" "${VISUAL:-}" "code" "cursor" "nvim" "vim" "vi" "nano")
for editor in "${editors[@]}"; do if [[ -n "$editor" ]] && command -v "$editor" &>/dev/null; then "$editor" "$file" return $? fi done
echo "No editor found" >&2 return 1 }
# =========================================================================== # Path Shims (for WSL interop) # ===========================================================================
# Convert to Windows path (WSL only) winpath() { local path="${1:?Path required}"
if [[ "$__SHIM_WSL" == "true" ]]; then wslpath -w "$path" else echo "$path" fi }
# Convert to Unix path unixpath() { local path="${1:?Path required}"
if [[ "$__SHIM_WSL" == "true" ]]; then wslpath -u "$path" elif [[ "$__SHIM_OS" == "windows" ]]; then echo "$path" | sed -e 's|\\|/|g' -e 's|^\([A-Za-z]\):|/\L\1|' else echo "$path" fi }
# =========================================================================== # List Directory Shims # ===========================================================================
# Enhanced ls with fallbacks l() { if command -v eza &>/dev/null; then eza -la --git --icons "$@" elif command -v exa &>/dev/null; then exa -la --git "$@" elif [[ "$__SHIM_OS" == "macos" ]]; then ls -laG "$@" else ls -la --color=auto "$@" fi }
# Tree with fallbacks t() { local depth="${1:-2}"
if command -v eza &>/dev/null; then eza --tree --level="$depth" --icons elif command -v tree &>/dev/null; then tree -L "$depth" else find . -maxdepth "$depth" -print | sed -e 's;[^/]*/;|____;g;s;____|; |;g' fi }
# =========================================================================== # Export message # ===========================================================================
if [[ "${SHIMS_LOADED:-}" != "true" ]]; then export SHIMS_LOADED="true" fi
